Suppose that Assumptions~1.2, 1.1, 1.3, 2.4 hold. Let
\begin{align}

  \bar{L} = 660508 \times \max\left\{\frac{L}{\alpha}, \frac{L p}{\alpha \tau}, \frac{\sqrt{L L_{\max}} p \sqrt{\omega \tau}}{\alpha \beta \sqrt{n}}, \frac{\sqrt{L L_{\max}} \sqrt{p} \sqrt{\omega \tau}}{\alpha \sqrt{\beta} \sqrt{n}}, \frac{L_{\max} \omega p^2}{\beta^2 n}, \frac{L_{\max} \omega}{n}\right\},
\end{align}
$\beta \leq \frac{1}{\omega + 1},$ and $\theta_{\min} = \frac{1}{4}\min\left\{1, \frac{\alpha}{p}, \frac{\tau}{p}, \frac{\beta}{p}\right\}.$
For all $t \geq 0,$ Algorithm~alg:bi_diana guarantees that
\begin{equation}
\begin{aligned}

  &\Gamma_{t+1}\left({\mathbb{E}}\left[f(z^{t+1}) - f(x^*)\right] + \kappa {\mathbb{E}}\left[\frac{1}{n}\sum_{i=1}^n \left\| h_i^{t+1} - \nabla f_i(z^{t+1}) \right\|^2\right] + \nu_{t+1} {\mathbb{E}}\left[\left\| w^{t+1} - u^{t+1} \right\|^2\right]\right.\\
    &\quad  \left.+ \rho {\mathbb{E}}\left[\left\| k^{t+1} - \nabla f(z^{t+1}) \right\|^2\right] + \lambda {\mathbb{E}}\left[\left\| v^{t+1} - \nabla f(z^{t+1}) \right\|^2\right]\right) + \frac{\bar{L} + \Gamma_{t+1} \mu}{2} {\mathbb{E}}\left[\left\| u^{t+1} - x^* \right\|^2\right]\\
    &\leq \Gamma_{t} \Bigg( {\mathbb{E}}\left[f(z^{t}) - f(x^*)\right] + \kappa {\mathbb{E}}\left[\frac{1}{n}\sum_{i=1}^n \left\| h_i^t - \nabla f_i(z^{t}) \right\|^2\right]  + \nu_{t} {\mathbb{E}}\left[\left\| w^t - u^t \right\|^2\right] \\
    &\qquad\qquad + \rho {\mathbb{E}}\left[\left\| k^{t} - \nabla f(z^t) \right\|^2\right] + \lambda {\mathbb{E}}\left[\left\| v^{t} - \nabla f(z^t) \right\|^2\right] \Bigg) + \frac{\bar{L} + \Gamma_{t} \mu}{2} {\mathbb{E}}\left[\left\| u^t - x^* \right\|^2\right]
\end{aligned}
\end{equation}
for some $\kappa,$ $\rho,$ $\lambda,$ $\nu_{t} \geq 0.$

Suppose that Assumptions~1.2, 1.1, 1.3, 2.4 hold. Let
\begin{align}
  \bar{L} = 660508 \times \max\left\{\frac{L}{\alpha}, \frac{L p}{\alpha \tau}, \frac{\sqrt{L L_{\max}} p \sqrt{\omega \tau}}{\alpha \beta \sqrt{n}}, \frac{\sqrt{L L_{\max}} \sqrt{p} \sqrt{\omega \tau}}{\alpha \sqrt{\beta} \sqrt{n}}, \frac{L_{\max} \omega p^2}{\beta^2 n}, \frac{L_{\max} \omega}{n}\right\},
\end{align}
$\beta = \frac{1}{\omega + 1},$ $\theta_{\min} = \frac{1}{4}\min\left\{1, \frac{\alpha}{p}, \frac{\tau}{p}, \frac{\beta}{p}\right\},$ $h_i^0 = \nabla f_i(z^{0})$ for all $i \in [n],$ $w^0 = u^0,$ $k^{0} = \nabla f(z^0),$ $v^{0} = \nabla f(z^0),$ and $\Gamma_0 \geq 1.$
Then Algorithm~alg:bi_diana guarantees that
\begin{equation}
\begin{aligned}

  {\mathbb{E}}\left[f(z^{T}) - f(x^*)\right] + \frac{\mu}{2} {\mathbb{E}}\left[\left\| u^{T} - x^* \right\|^2\right] \leq 2\exp\left(-\frac{T}{Q}\right)\left(\left(f(z^{0}) - f(x^*)\right) + \left(\frac{\bar{L}}{\Gamma_{0}} + \mu\right) \left\| u^0 - x^* \right\|^2\right),
\end{aligned}
\end{equation}
where
\begin{align*}
  &Q := 2 \times \sqrt{660508} \times \\
  &\max\Bigg\{\sqrt{\frac{L}{\alpha p \mu}},\sqrt{\frac{L}{\alpha \tau \mu}},\sqrt{\frac{\sqrt{L L_{\max}} (\omega + 1) \sqrt{\omega \tau}}{\alpha \sqrt{n} \mu}},\sqrt{\frac{\sqrt{L L_{\max}} \sqrt{\omega + 1} \sqrt{\omega \tau}}{\alpha \sqrt{p} \sqrt{n} \mu}},\sqrt{\frac{L_{\max} \omega (\omega + 1)^2 p}{n \mu}}, \sqrt{\frac{L_{\max} \omega}{n p \mu}}, \\
  & \qquad \quad \frac{1}{\alpha}, \frac{1}{\tau}, (\omega + 1), \frac{1}{p}\Bigg\}.
\end{align*}

Suppose that Assumptions~1.2, 1.1, 1.3, 2.4 hold. Let
\begin{align}
  \bar{L} = 660508 \times \max\left\{\frac{L}{\alpha}, \frac{L p}{\alpha \tau}, \frac{\sqrt{L L_{\max}} p \sqrt{\omega \tau}}{\alpha \beta \sqrt{n}}, \frac{\sqrt{L L_{\max}} \sqrt{p} \sqrt{\omega \tau}}{\alpha \sqrt{\beta} \sqrt{n}}, \frac{L_{\max} \omega p^2}{\beta^2 n}, \frac{L_{\max} \omega}{n}\right\},
\end{align}
$\beta = \frac{1}{\omega + 1},$ $\theta_{\min} = \frac{1}{4}\min\left\{1, \frac{\alpha}{p}, \frac{\tau}{p}, \frac{\beta}{p}\right\},$ $h_i^0 = \nabla f_i(z^{0})$ for all $i \in [n],$ $w^0 = u^0,$ $k^{0} = \nabla f(z^0),$ $v^{0} = \nabla f(z^0),$ and $\Gamma_0 \in [1, \nicefrac{\bar{L}}{L}].$
Then Algorithm~alg:bi_diana returns $\varepsilon$-solution, i.e., ${\mathbb{E}}\left[f(z^{T})\right]- f(x^*) \leq \varepsilon,$ after
\begin{equation}
\begin{aligned}

    T = 
    \begin{cases}
      \Theta\left(\frac{1}{p \theta_{\min}} \log \frac{\bar{L} \left\| z^0 - x^* \right\|^2}{\Gamma_0 \varepsilon}\right), &\frac{\bar{L} \left\| z^0 - x^* \right\|^2}{\varepsilon} < \frac{1}{p \theta_{\min}^2} \\
      \Theta\left(\max\left\{\frac{1}{p \theta_{\min}} \log \frac{1}{\Gamma_0 p \theta_{\min}^2}, 0\right\} + Q\sqrt{\frac{\left\| z^0 - x^* \right\|^2}{\varepsilon}}\right), & \textnormal{otherwise}
    \end{cases}
\end{aligned}
\end{equation}
iterations,
where
$$Q := \Theta\left(\max\left\{\sqrt{\frac{L}{\alpha p}}, \sqrt{\frac{L}{\alpha \tau}}, \sqrt{\frac{\sqrt{L L_{\max}} (\omega + 1)\sqrt{\omega \tau}}{\alpha \sqrt{n}}}, \sqrt{\frac{\sqrt{L L_{\max}} \sqrt{\omega + 1} \sqrt{\omega \tau}}{\alpha \sqrt{p} \sqrt{n}}}, \sqrt{\frac{L_{\max} \omega (\omega + 1)^2 p}{n}}, \sqrt{\frac{L_{\max} \omega}{n p}}\right\}\right).$$
